#!/bin/sh
#
# Post-removal script of the app's .deb and .rpm (generated by grafida/shell-packager).
#
# Refreshes the desktop and icon caches and, on a final removal only (never on an upgrade), deletes
# what the app made inside its own directory while it ran, so nothing is left in /opt/NAME. The
# user's data lives in their own home directory and is never touched.
#
# dpkg: $1 is remove, purge, upgrade, … rpm: $1 is the number of instances left (0 = final).

set -e

NAME=@NAME@
APPS_DIR=/usr/share/applications
ICONS_DIR=/usr/share/icons/hicolor

case ${1:-} in
    remove | purge | 0) rm -rf "/opt/$NAME" ;;
esac

if command -v update-desktop-database >/dev/null 2>&1; then update-desktop-database -q "$APPS_DIR" || true; fi
if command -v gtk-update-icon-cache >/dev/null 2>&1 && [ -d "$ICONS_DIR" ]; then gtk-update-icon-cache -q -f -t "$ICONS_DIR" || true; fi

exit 0
